    };

    setObjects((prev) => [...prev, newObject]);
  };

  return (
    <>
      <SoftShadows size={15} samples={10} focus={1} />

      {/* Invisible Click Plane for Spawning */}
      <mesh 
        position={[0, 0, 0]} 
        rotation={[-Math.PI / 2, 0, 0]} 
        onClick={spawnObject}
        visible={false}
